import re


def closest_integer(value):
    # Convert the input value to float
    number = float(value)

    # Extract the integer part and the decimal part of the number
    integer_part, decimal_part = divmod(abs(number), 1)

    # If the decimal part is not exactly .5, return the integer part
    if decimal_part < 0.5:
        return int(integer_part)
    else:
        # If the decimal part is exactly .5 and the integer part is even, round down
        # Otherwise, round up
        if integer_part % 2 == 0:
            return int(integer_part)
        else:
            return int(integer_part + 1)

