def bf(planet1, planet2):
    import collections

    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    order = {planet: index for index, planet in enumerate(planets)}

    sorted_planets = sorted(planets, key=lambda x: order[x])

    if planet1 not in order or planet2 not in order:
        return ()

    start_index = order[planet1]
    end_index = order[planet2]

    if start_index > end_index:
        start_index, end_index = end_index, start_index

    return tuple(sorted_planets[start_index:end_index+1])

```

